<?php require __DIR__.'/../includes/bootstrap.php'; if(logged_in()) redirect('dashboard.php'); $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf(); $email=post('email');$password=post('password'); if($email===''||$password==='')$error='Enter your email and password.'; elseif(login_user($db,$email,$password)){session_regenerate_id(true);redirect('dashboard.php');}else $error='Incorrect email address or password.';} $system=setting($db,'system_name',$config['app_name']);?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Login | <?=e($system)?></title><link rel="stylesheet" href="assets/css/app.css"></head><body class="login"><div class="panel"><h2><?=e($system)?></h2><?php if($error): ?><div class="alert error"><?=e($error)?></div><?php endif; ?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><p><label>Email</label><input type="email" name="email" required autocomplete="username"></p><p><label>Password</label><input type="password" name="password" required autocomplete="current-password"></p><button class="btn" type="submit">Login</button> <a href="forgot_password.php">Forgot password?</a></form></div></body></html>